gRb(){return"\u062e\u0644\u0641\u064a\u062a\u064a \u0641\u064a \u062a\u0637\u0648\u064a\u0631 \u0623\u0646\u0638\u0645\u0629 .NET \u0648 ERP (\u0645\u062d\u0627\u0633\u0628\u0629\u060c \u0645\u062e\u0627\u0632\u0646\u060c \u0645\u0628\u064a\u0639\u0627\u062a) \u0645\u0646\u062d\u062a\u0646\u064a \u0641\u0647\u0645\u0627\u064b \u0639\u0645\u064a\u0642\u0627\u064b \u0644\u0645\u0646\u0637\u0642 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u0639\u0642\u062f \u0648\u062a\u0635\u0645\u064a\u0645 \u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0645\u0648\u062b\u0648\u0642\u0629 \u0644\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0641\u0639\u0644\u064a."},
gRe(){return"\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0648\u0633\u0639"},
gRf(){return"\u0645\u0628\u0646\u064a\u0629 \u0644\u0627\u0633\u062a\u064a\u0639\u0627\u0628 \u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0639\u0627\u0644\u064a \u062f\u0648\u0646 \u0645\u0634\u0627\u0643\u0644 \u0641\u064a \u0627\u0644\u0623\u062f\u0627\u0621."},
gRh(){return"\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0627\u062e\u062a\u0628\u0627\u0631"},
gRi(){return"\u0645\u0639\u0645\u0627\u0631\u064a\u0629 \u0645\u0641\u0635\u0648\u0644\u0629 \u062a\u062a\u064a\u062d \u0643\u062a\u0627\u0628\u0629 \u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0648\u062d\u062f\u0629 \u0648\u0648\u0627\u062c\u0647\u0627\u062a \u0648\u062a\u0643\u0627\u0645\u0644 \u0645\u0648\u062b\u0648\u0642\u0629."},
gRc(){return"\u0633\u0647\u0644\u0629 \u0627\u0644\u0635\u064a\u0627\u0646\u0629"},
gRd(){return"\u0643\u0648\u062f \u0645\u0646\u0638\u0645 \u0648\u0633\u0647\u0644 \u0627\u0644\u062a\u0648\u0633\u0639\u0629 \u0648\u0627\u0644\u062a\u062d\u062f\u064a\u062b \u0628\u0623\u0645\u0627\u0646."},
gE6(){return"\u0625\u062a\u0642\u0627\u0646 \u0648\u0627\u062c\u0647\u0627\u062a \u0627\u0644\u062c\u0648\u0627\u0644"},
gE5(){return"\u0648\u0627\u062c\u0647\u0627\u062a \u0645\u062a\u062c\u0627\u0648\u0628\u0629 \u0628\u062f\u0642\u0629 \u0648\u0633\u0631\u0639\u0629 60 \u0625\u0637\u0627\u0631\u0627\u064b \u0641\u064a \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0639\u0644\u0649 Android \u0648 iOS \u0648\u0627\u0644\u0648\u064a\u0628 \u0645\u0639 \u062d\u0631\u0643\u0627\u062a \u0633\u0644\u0633\u0629."},
gE8(){return"\u0645\u0639\u0645\u0627\u0631\u064a\u0629 \u0628\u0631\u0645\u062c\u064a\u0629 \u0645\u062a\u064a\u0646\u0629"},
gE7(){return"Clean Architecture \u0648\u0645\u0628\u0627\u062f\u0626 SOLID \u0648\u062d\u0642\u0646 \u0627\u0644\u062a\u0628\u0639\u064a\u0627\u062a (GetIt) \u0648\u0641\u0635\u0644 \u0643\u0627\u0645\u0644 \u0644\u0645\u0646\u0637\u0642 \u0627\u0644\u0623\u0639\u0645\u0627\u0644."},
gEa(){return"\u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0633\u062d\u0627\u0628\u064a\u0629 \u0648\u0627\u0644\u0645\u0624\u0633\u0633\u064a\u0629"},
gE9(){return"\u0631\u0628\u0637 \u0645\u0639 Supabase \u0648 Firebase \u0648 REST APIs \u0648 SQL Server \u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u0640 Backend \u0627\u0644\u0641\u0639\u0644\u064a\u0629."},
gIP(){return"\u0627\u0644\u062a\u0631\u0633\u0627\u0646\u0629 \u0627\u0644\u062a\u0642\u0646\u064a\u0629"},
gIO(){return"\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0645\u0635\u0646\u0641\u0629"},
gIM(){return"\u062a\u0637\u0648\u064a\u0631 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u062c\u0648\u0627\u0644"},
gIJ(){return"\u0627\u0644\u0645\u0639\u0645\u0627\u0631\u064a\u0629 \u0648\u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0635\u0645\u064a\u0645"},
gIK(){return"\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0633\u062d\u0627\u0628\u064a\u0629 \u0648\u0627\u0644\u062e\u0644\u0641\u064a\u0629"},
gIN(){return"\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u062d\u0644\u064a"},
