gII(){return"\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0648\u0627\u0644\u0625\u0646\u062a\u0627\u062c\u064a\u0629"},
gVU(){return"\u0623\u0628\u0631\u0632 \u0627\u0644\u0623\u0639\u0645\u0627\u0644"},
gVT(){return"\u0645\u0634\u0627\u0631\u064a\u0639 \u062a\u0637\u0628\u064a\u0642\u064a\u0629 \u062d\u0642\u064a\u0642\u064a\u0629"},
gVO(){return"\u0645\u0634\u0631\u0648\u0639 \u0645\u0645\u064a\u0632"},
gH7(){return"\u0627\u0633\u062a\u0639\u0631\u0627\u0636 \u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0645\u0634\u0631\u0648\u0639"},
gH6(){return"\u0627\u0644\u0643\u0648\u062f \u0627\u0644\u0645\u0635\u062f\u0631\u064a"},
