gVR(){return"\u0645\u064a\u0632\u0627\u062a \u0648\u0641\u0648\u0627\u0626\u062f \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0646\u0647\u0627\u0626\u064a"},
gVS(){return"\u0645\u0635\u0645\u0645\u0629 \u0644\u062a\u0648\u0641\u064a\u0631 \u062a\u062c\u0631\u0628\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0633\u0647\u0644\u0629 \u0648\u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u062f\u0648\u0646 \u062a\u0639\u0642\u064a\u062f\u0627\u062a \u062a\u0642\u0646\u064a\u0629"},
gVM(){return"\u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0648\u0627\u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0647\u0646\u062f\u0633\u064a\u0629"},
gzu(){return"\u0627\u0644\u0639\u0648\u062f\u0629 \u0644\u0644\u0631\u0626\u064a\u0633\u064a\u0629"},
gVP(){return"\u0645\u0639\u0631\u0636 \u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0648\u0627\u062c\u0647\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645"},
gVQ(){return"\u0627\u0633\u062a\u0639\u0631\u0627\u0636 \u0644\u0623\u0647\u0645 \u0634\u0627\u0634\u0627\u062a \u0648\u062a\u062c\u0631\u0628\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0628\u0646\u064a\u0629 \u0628\u0640 Flutter"},
gTG(){return"\u0627\u0644\u0645\u0633\u064a\u0631\u0629 \u0648\u0627\u0644\u062e\u0628\u0631\u0629"},
