gTE(){return"\u0645\u0637\u0648\u0631 \u062a\u0637\u0628\u064a\u0642\u0627\u062a Flutter"},
gTB(){return"\u0645\u0634\u0627\u0631\u064a\u0639 \u062d\u0631\u0629 \u0648\u0645\u0633\u062a\u0642\u0644\u0629 (Freelance)"},
gTD(){return"2024 \u2014 \u062d\u062a\u0649 \u0627\u0644\u0622\u0646"},
gTC(){return"\u0628\u0646\u0627\u0621 \u0648\u0647\u0646\u062f\u0633\u0629 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0645\u062a\u0643\u0627\u0645\u0644\u0629 \u062a\u0639\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u062c\u0648\u0627\u0644 \u0648\u0627\u0644\u0648\u064a\u0628 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Flutter \u0648 Dart \u0648 BLoC \u0645\u0639 \u062a\u0637\u0628\u064a\u0642 Clean Architecture \u0648\u0627\u0644\u0631\u0628\u0637 \u0645\u0639 Supabase \u0648 Firebase."},
gTA(){return"\u0645\u0637\u0648\u0631 \u0623\u0646\u0638\u0645\u0629 \u062f\u064a\u0633\u0643\u062a\u0648\u0628 C# WinForms & ERP"},
gTx(){return"\u0645\u0637\u0648\u0631 \u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0645\u0633\u062a\u0642\u0644 (Freelance)"},
