gTt(){return"\u0623\u0648\u0631\u0627\u0633\u0643\u0648\u0645 \u0644\u0644\u0625\u0646\u0634\u0627\u0621\u0627\u062a (Orascom Construction)"},
gTv(){return"\u0628\u064a\u0626\u0629 \u0634\u0631\u0643\u0627\u062a \u0643\u0628\u0631\u0649"},
gTu(){return"\u0625\u062f\u0627\u0631\u0629 \u0639\u0645\u0644\u064a\u0627\u062a \u062a\u062f\u0641\u0642 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0628\u062f\u0642\u0629 \u0648\u0645\u0648\u062b\u0648\u0642\u064a\u0629 \u0639\u0627\u0644\u064a\u0629\u060c \u0645\u0645\u0627 \u0645\u0646\u062d\u0646\u064a \u0641\u0647\u0645\u0627\u064b \u0639\u0645\u0644\u064a\u0627\u064b \u0644\u0622\u0644\u064a\u0627\u062a \u0627\u0644\u0639\u0645\u0644 \u0641\u064a \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0646\u0639\u0643\u0633 \u0644\u0627\u062d\u0642\u0627\u064b \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0623\u0646\u0638\u0645\u0629 \u0628\u0631\u0645\u062c\u064a\u0629 \u0633\u0647\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645."},
gTs(){return"\u062e\u0644\u0641\u064a\u0629 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0645\u0624\u0633\u0633\u064a\u0629 \u0648\u0627\u0644\u0640 ERP"},
